package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen0Test {

    private Document doc;
    private FormElement form;

    @Before
    public void setUp() {
        doc = Document.create("");
        form = doc.createElement("form");
        doc.body().appendChild(form);
    }

    @Test
    public void testEmptyForm() {
        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testNonSubmittableElement() {
        // Using a tag that is not form submittable (e.g., div)
        Element div = doc.createElement("div");
        div.attr("name", "test");
        form.appendChild(div);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testDisabledElement() {
        Element input = doc.createElement("input");
        input.attr("name", "test");
        input.attr("disabled", "");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testNoNameAttribute() {
        Element input = doc.createElement("input");
        input.attr("type", "text");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testStandardTextInput() {
        Element input = doc.createElement("input");
        input.attr("name", "username");
        input.attr("type", "text");
        input.attr("value", "john_doe");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("username", result.get(0).getKey());
        Assert.assertEquals("john_doe", result.get(0).getValue());
    }

    @Test
    public void testCheckboxCheckedWithValue() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("name", "agree");
        checkbox.attr("type", "checkbox");
        checkbox.attr("value", "yes");
        checkbox.attr("checked", "");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("agree", result.get(0).getKey());
        Assert.assertEquals("yes", result.get(0).getValue());
    }

    @Test
    public void testCheckboxCheckedNoValue() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("name", "active");
        checkbox.attr("type", "checkbox");
        checkbox.attr("checked", "");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("active", result.get(0).getKey());
        Assert.assertEquals("on", result.get(0).getValue());
    }

    @Test
    public void testRadioUnchecked() {
        Element radio = doc.createElement("input");
        radio.attr("name", "gender");
        radio.attr("type", "radio");
        radio.attr("value", "m");
        // No checked attribute
        form.appendChild(radio);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testSelectWithSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "color");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.text("Red");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "");
        opt2.text("Blue");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("color", result.get(0).getKey());
        Assert.assertEquals("blue", result.get(0).getValue());
    }

    @Test
    public void testSelectMultipleSelectedOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "tags");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "java");
        opt1.attr("selected", "");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "junit");
        opt2.attr("selected", "");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(2, result.size());
        Assert.assertEquals("java", result.get(0).getValue());
        Assert.assertEquals("junit", result.get(1).getValue());
    }

    @Test
    public void testSelectFirstOptionIfNoneSelected() {
        Element select = doc.createElement("select");
        select.attr("name", "city");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "NY");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "LA");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("NY", result.get(0).getValue());
    }

    @Test
    public void testSelectEmpty() {
        Element select = doc.createElement("select");
        select.attr("name", "empty");
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testCaseInsensitiveType() {
        Element input = doc.createElement("input");
        input.attr("name", "check");
        input.attr("type", "CHECKBOX"); // Uppercase
        input.attr("checked", "");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("check", result.get(0).getKey());
    }
}
